public class HandleVal extends JavacASTAdapter {
	private JavacResolution resolution;
	private final Set<JCTree> alreadyHandled = new HashSet<JCTree>();

	private static boolean eq(String typeTreeToString, String key) {
		return typeTreeToString.equals(key) || typeTreeToString.equals("lombok." + key) || typeTreeToString.equals("lombok.experimental." + key);
	}

	@SuppressWarnings("deprecation") @Override
	public void visitLocal(JavacNode localNode, JCVariableDecl local) {
		JCTree typeTree = local.vartype;
		if (typeTree == null) return;
		String typeTreeToString = typeTree.toString();
		JavacNode typeNode = localNode.getNodeFor(typeTree);

		if (!(eq(typeTreeToString, "val") || eq(typeTreeToString, "var"))) return;
		boolean isVal = typeMatches(val.class, localNode, typeTree);
		boolean isVar = typeMatches(var.class, localNode, typeTree);
		if (!(isVal || isVar)) return;
		if (!alreadyHandled.add(local)) return;

		handleValVar(localNode, local, typeNode, typeTreeToString, isVal, isVar);
	}

	private void handleValVar(JavacNode localNode, JCVariableDecl local, JavacNode typeNode, String annotation, boolean isVal, boolean isVar) {
		JavacNode parentNode = localNode.directUp();
		JCTree parentRaw = parentNode.get();
		if (isVal && parentRaw instanceof JCForLoop) {
			localNode.addError("'val' is not allowed in old-style for loops");
			return;
		}

		if (parentRaw instanceof JCForLoop && ((JCForLoop) parentRaw).getInitializer().size() > 1) {
			localNode.addError("'var' is not allowed in old-style for loops if there is more than 1 initializer");
			return;
		}

		if (local.init == null && !(parentRaw instanceof JCEnhancedForLoop)) {
			localNode.addError("'" + annotation + "' on a local variable requires an initializer expression");
			return;
		}

		if (isVar && local.init instanceof JCLiteral && ((JCLiteral) local.init).value == null) {
			if (local.init.type == null) {
				localNode.addError("variable initializer is 'null'");
			}
		}

		if (ifTypeIsIterableToComponent(localNode, local, typeNode, parentRaw, parentNode, isVal, annotation)) {
			localNode.getAst().setChanged();
		}
	}

	/**
	 * Resolves any 'val' or 'var' local declarations nested inside the given expression (e.g. inside a lambda body), so that
	 * they have a real type by the time the surrounding declaration is resolved. Without this, javac would resolve the nested
	 * 'val' keyword to the lombok.val annotation class itself, which then poisons type inference of the surrounding expression.
	 */
	private boolean resolveNestedVals(final JavacNode node, JCTree tree) {
		final ListBuffer<JavacNode> nestedVals = new ListBuffer<JavacNode>();
		new TreeScanner() {
			@Override public void visitClassDef(JCClassDecl tree) {
				// Do not descend into (anonymous) class declarations; val/var is not applicable to their members anyway.
			}

			@Override public void visitVarDef(JCVariableDecl vd) {
				if (vd.vartype != null) {
					String s = vd.vartype.toString();
					if (eq(s, "val") || eq(s, "var")) {
						JavacNode n = node.getNodeFor(vd);
						if (n != null) nestedVals.append(n);
					}
				}
				super.visitVarDef(vd);
			}
		}.scan(tree);

		boolean changed = false;
		for (JavacNode nestedNode : nestedVals) {
			JCVariableDecl nested = (JCVariableDecl) nestedNode.get();
			JCTree typeTree = nested.vartype;
			if (typeTree == null) continue;
			String typeTreeToString = typeTree.toString();
			if (!(eq(typeTreeToString, "val") || eq(typeTreeToString, "var"))) continue;
			if (!alreadyHandled.add(nested)) continue;
			boolean isVal = typeMatches(val.class, nestedNode, typeTree);
			boolean isVar = typeMatches(var.class, nestedNode, typeTree);
			if (!(isVal || isVar)) continue;
			handleValVar(nestedNode, nested, nestedNode.getNodeFor(typeTree), typeTreeToString, isVal, isVar);
			changed = true;
		}
		return changed;
	}

	private static boolean isValOrVarType(Type type) {
		if (type == null) return false;
		TypeSymbol symbol = type.asElement();
		if (symbol == null) return false;
		String qualifiedName = symbol.getQualifiedName().toString();
		return qualifiedName.equals("lombok.val") || qualifiedName.equals("lombok.var");
	}

	private Type resolveAndRepair(JavacNode node, JCTree treeToResolve) {
		Type type = ((JCExpression) this.resolution.resolveMethodMember(node).get(treeToResolve)).type;
		if (type == null || type.isErroneous() || isValOrVarType(type)) {
			if (resolveNestedVals(node, treeToResolve)) {
				type = ((JCExpression) this.resolution.resolveMethodMember(node).get(treeToResolve)).type;
			}
		}
		return type;
	}

